function getCart(){try{return JSON.parse(localStorage.getItem('tv_cart'))||[]}catch(e){return[]}}
function saveCart(c){localStorage.setItem('tv_cart',JSON.stringify(c));updateBadges()}
function getWishlist(){try{return JSON.parse(localStorage.getItem('tv_wishlist'))||[]}catch(e){return[]}}
function saveWishlist(w){localStorage.setItem('tv_wishlist',JSON.stringify(w));updateBadges()}
function addToCart(id,qty){var c=getCart(),e=c.find(function(i){return i.id===id});if(e){e.qty+=qty||1}else{var p=PRODUCTS.find(function(x){return x.id===id});if(p)c.push({id:p.id,name:p.name,emoji:p.emoji,subcategory:p.subcategory,price:p.price,qty:qty||1})}saveCart(c)}
function removeFromCart(id){saveCart(getCart().filter(function(i){return i.id!==id}))}
function updateCartQty(id,qty){var c=getCart(),i=c.find(function(x){return x.id===id});if(i){i.qty=Math.max(1,qty);saveCart(c)}}
function toggleWishlist(id){var w=getWishlist();if(w.indexOf(id)>-1){w=w.filter(function(x){return x!==id})}else{w.push(id)}saveWishlist(w);return w.indexOf(id)>-1}
function isInWishlist(id){return getWishlist().indexOf(id)>-1}
function updateBadges(){var cc=getCart().reduce(function(s,i){return s+i.qty},0),wc=getWishlist().length;document.querySelectorAll('.cart-badge').forEach(function(b){b.textContent=cc;b.style.display=cc>0?'flex':'none'});document.querySelectorAll('.wishlist-badge').forEach(function(b){b.textContent=wc;b.style.display=wc>0?'flex':'none'})}
function formatPrice(n){return'Rs '+n.toLocaleString('en-PK')}
function renderStars(r){var s='';for(var i=1;i<=5;i++){s+=i<=Math.floor(r)?'\u2605':(i-0.5<=r?'\u2605':'\u2606')}return s}
function getProductById(id){return PRODUCTS.find(function(p){return p.id===parseInt(id)})}
function getRelatedProducts(p,lim){return PRODUCTS.filter(function(x){return x.category===p.category&&x.id!==p.id}).slice(0,lim||4)}
document.addEventListener('DOMContentLoaded',function(){updateBadges();var hamburger=document.querySelector('.hamburger-menu');var overlay=document.getElementById('mobileMenuOverlay');var closeBtn=document.getElementById('mobileMenuClose');if(hamburger&&overlay){hamburger.addEventListener('click',function(){overlay.classList.add('open')})}if(closeBtn&&overlay){closeBtn.addEventListener('click',function(){overlay.classList.remove('open')});overlay.addEventListener('click',function(e){if(e.target===overlay)overlay.classList.remove('open')})}var backToTop=document.getElementById('backToTop');if(backToTop){window.addEventListener('scroll',function(){if(window.scrollY>400)backToTop.classList.add('visible');else backToTop.classList.remove('visible')});backToTop.addEventListener('click',function(){window.scrollTo({top:0,behavior:'smooth'})})}});
